// The previous (Jekyll + Chirpy) site registered a caching service worker at this address.
// Browsers that still have it fetch this file when they check for an update.
// This replacement deletes every cache, unregisters itself, and reloads open pages
// so that returning visitors get the current site. It can be removed once old visitors have updated.
self.addEventListener('install', function () {
  self.skipWaiting();
});

self.addEventListener('activate', function (event) {
  event.waitUntil(
    (async function () {
      var keys = await caches.keys();
      await Promise.all(keys.map(function (key) { return caches.delete(key); }));
      await self.registration.unregister();
      var clients = await self.clients.matchAll({ type: 'window' });
      clients.forEach(function (client) { client.navigate(client.url); });
    })()
  );
});
